describe('Multi-step Form Navigation - Back Button', () => {
  beforeEach(() => {
    cy.visit('/multi-step-form');
  });

  it('should navigate back to previous step without losing form data', () => {
    // Step 1: Personal Information
    cy.get('[data-testid="step-1-name-input"]').type('John Doe');
    cy.get('[data-testid="step-1-email-input"]').type('john@example.com');
    cy.get('[data-testid="step-1-phone-input"]').type('555-123-44');
    cy.get('[data-testid="step-1-next-button"]').click();

    // Step 2: Address Information
    cy.get('[data-testid="step-2-address-input"]').type('123 Main St');
    cy.get('[data-testid="step-2-city-input"]').type('Anytown');
    cy.get('[data-testid="step-2-zip-input"]').type('12345');
    cy.get('[data-testid="step-2-next-button"]').click();

    // Step 3: Review and Submit
    cy.get('[data-testid="step-3-review-button"]').click();

    // Navigate back to Step 2
    cy.get('[data-testid="step-2-back-button"]').click();

    // Verify data is preserved in Step 2
    cy.get('[data-testid="step-2-address-input"]').should('have.value', '123 Main St');
    cy.get('[data-testid="step-2-city-input"]').should('have.value', 'Anytown');
    cy.get('[data-testid="step-2-zip-input"]').should('have.value', '12345');

    // Navigate back to Step 1
    cy.get('[data-testid="step-1-back-button"]').click();

    // Verify data is preserved in Step 1
    cy.get('[data-testid="step-1-name-input"]').should('have.value', 'John Doe');
    cy.get('[data-testid="step-1-email-input"]').should('have.value', 'john@example.com');
    cy.get('[data-testid="step-1-phone-input"]').should('have.value', '555-123-44');

    // Navigate forward to Step 2 again
    cy.get('[data-testid="step-1-next-button"]').click();
    cy.get('[data-testid="step-2-next-button"]').click();

    // Navigate forward to Step 3
    cy.get('[data-testid="step-3-review-button"]').click();

    // Verify form is still valid and ready for submission
    cy.get('[data-testid="step-3-submit-button"]').should('be.visible');
  });

  it('should handle back navigation when form data is incomplete', () => {
    // Step 1: Partial data entry
    cy.get('[data-testid="step-1-name-input"]').type('Jane');
    cy.get('[data-testid="step-1-email-input"]').type('jane@example.com');
    // Do not fill phone number

    // Attempt to proceed to Step 2 (should fail validation)
    cy.get('[data-testid="step-1-next-button"]').click();

    // Verify validation error appears
    cy.get('[data-testid="step-1-phone-input"]').should('have.class', 'error');
    cy.get('[data-testid="step-1-error-message"]').should('contain', 'Phone number is required');

    // Navigate back to Step 1 (should not change state)
    cy.get('[data-testid="step-1-back-button"]').click();

    // Verify error message persists
    cy.get('[data-testid="step-1-error-message"]').should('be.visible');

    // Verify partial data is still present
    cy.get('[data-testid="step-1-name-input"]').should('have.value', 'Jane');
    cy.get('[data-testid="step-1-email-input"]').should('have.value', 'jane@example.com');

    // Fill in missing data and proceed
    cy.get('[data-testid="step-1-phone-input"]').type('555-999-00');
    cy.get('[data-testid="step-1-next-button"]').click();

    // Verify validation error is cleared
    cy.get('[data-testid="step-1-phone-input"]').should('not.have.class', 'error');
    cy.get('[data-testid="step-1-error-message"]').should('not.exist');

    // Navigate back to Step 1
    cy.get('[data-testid="step-2-back-button"]').click();

    // Verify data is still preserved
    cy.get('[data-testid="step-1-name-input"]').should('have.value', 'Jane');
    cy.get('[data-testid="step-1-email-input"]').should('have.value', 'jane@example.com');
    cy.get('[data-testid="step-1-phone-input"]').should('have.value', '555-999-00');
  });
});
